sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float width;
uniform float position;
layout(color) uniform half4 strokeColor;
uniform float strokeOpacity;
uniform float softness;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float amax = c.a;
    float amin = c.a;
    for (int k = 0; k < 3; k++) {
        float rr = width * (float(k) + 1.0) / 3.0 * (position < 1.5 ? 1.0 : 0.5);
        for (int i = 0; i < 12; i++) {
            float a = float(i) * 0.5235988;
            float al = tex(coord + float2(cos(a), sin(a)) * rr).a;
            amax = max(amax, al);
            amin = min(amin, al);
        }
    }
    float outerS = pow(saturate(amax - c.a), 1.0 - softness * 0.7) * strokeOpacity;
    float innerS = pow(saturate(c.a - amin), 1.0 - softness * 0.7) * strokeOpacity;
    float3 sc = float3(strokeColor.rgb);
    float4 r = c;
    if (position < 0.5 || position > 1.5) r = c + float4(sc * outerS, outerS) * (1.0 - c.a);
    if (position > 0.5) r = float4(mix(r.rgb, sc * c.a, innerS), r.a);
    return fin(c, r, opacity);
}
